@js:
sort=[];
push=(title,url,type)=> sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: 1,
				layout_flexBasisPercent: type
			}
	});



url = source.getKey().replace('www.','m.');
$$=(uri)=>`${url}/${uri}/<,{{page}\}.html>`;
[
["全部分类","allsort"],
["玄幻奇幻","xuanhuan"],
["武侠仙侠","wuxia"],
["都市生活","dushi"],
["历史军事","lishi"],
["游戏竞技","youxi"],
["科幻未来","kehuan"],
["恐怖悬疑","xuanyi"],
["其他类型","qita"],
["古代言情","guyan"],
["现代言情","xianyan"],
["幻想奇缘","huanqing"],
["游戏情缘","zongcai"],
["浪漫青春","qingchun"],
["言情美文","wangluo"],
["科幻灵异","mmkehuan"],
["其他类型","mmqita"]
].map([title,uri]=>{
		push(title,$$(uri),0.25);
	});
JSON.stringify(sort);

